    { x: -30, y: -95, r: 14 },
    { x: -16, y: -116, r: 16 },
    { x: 4, y: -122, r: 16 },
    { x: 24, y: -112, r: 15 },
    { x: 32, y: -92, r: 13 },
  ];
  for (const c of curls) {
    ctx.strokeStyle = "#ce93d8";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, -82);
    ctx.quadraticCurveTo(c.x * 0.6, c.y + 15, c.x, c.y);
    ctx.stroke();
